			call.Status, call.Error = 400, "model does not support image input"
			group := ""
			if isGroup {
				group = g.Name
			}
			writeError(w, from, 400, fmt.Sprintf("model %q does not support image input%s%s", call.Model, textOnlyNote(p, model, group), noSeerNote()))
			turnedAway()
			return
		}
	}
