			s.trace.update(tr, func(t *Route) {
				tt := &t.Tries[len(t.Tries)-1]
				tt.Done, tt.Status, tt.Error, tt.Queued, tt.Millis = true, call.Status, call.Error, queued, time.Since(began).Milliseconds()
