    } catch (e) { say(t(e.message)); return false; }
  };
  ed.addEventListener("paste", (e) => {
    const text = e.clipboardData?.getData("text") || "";
    if (!text.includes("magpie-sync:")) return;
    e.preventDefault();
    pasted = text;
    openPasted();
  });
  phrase.addEventListener("keydown", (e) => { if (e.key === "Enter" && pasted) openPasted(); });
  phrase.addEventListener("change", () => { if (pasted) openPasted(); });
  cancel.onclick = () => { syncOpen = ""; renderSync(); };
  off.onclick = async () => { syncOpen = ""; renderSync(await api("davsync/off", {}).catch(() => null) || undefined); };
  // form: the setup as typed, or a reason it can't be saved yet
  const form = () => {
    const b = bucket.value.trim(), p = prefix.value.trim().replace(/^\/+|\/+$/g, "");
    if (kind === "s3" && !b) return t("Name the bucket");
    const repository = repo.value.trim().replace(/^https:\/\/github\.com\//i, "").replace(/\/+$/, "").replace(/\.git$/i, "");
    const ghFolder = ghPrefix.value.trim().replace(/^\/+|\/+$/g, "");
    if (kind === "github" && !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repository)) return t("Name the GitHub repository as owner/repo");
    if (kind === "github" && !gh.passwordSet && !token.value.trim()) return t("Enter a GitHub token with Contents read and write permission");
    if (!v.passphraseSet && !phrase.value) return t("Pick a passphrase: the file is sealed with it");
    const where = kind === "github"
      ? { url: "github://" + repository + (ghFolder ? "/" + ghFolder : ""), branch: branch.value.trim(), password: token.value.trim() }
      : kind === "s3"
      ? { url: "s3://" + b + (p ? "/" + p : ""), user: keyID.value.trim(), password: secret.value, endpoint: endpoint.value.trim(), region: region.value.trim(), pathStyle: pathStyle.checked }
      : { url: url.value.trim(), user: user.value.trim(), password: pass.value };
    // a part left out is said; one synced only when it was left out before,
    // so a setup from before the choice is saved as it was
    const outs = {};
    for (const [k, c] of [["providers", prov], ["settings", sets], ["profiles", prof]]) if (!c.checked || v[k] === false) outs[k] = c.checked;
    return { ...where, passphrase: phrase.value, keys: keys.checked, agents: agents.checked, library: lib.checked, memory: mem.checked, ...outs, ...(use.checked || v.usage ? { usage: use.checked } : {}), ...(si.checked || v.signIns ? { signIns: si.checked } : {}), ...(own.checked || v.providerSettingsHere ? { providerSettingsHere: own.checked } : {}), ...(except.length || v.signInsExcept?.length ? { signInsExcept: except } : {}) };
  };
  peek.onclick = async () => {
    if (!(await openPasted())) return;
    const f = form();
    if (typeof f === "string") return say(f);
    peek.classList.add("busy");
    try { askSyncPreview(await api("davsync/preview", { form: f }), () => save.click()); } catch (e) { say(t(e.message)); }
    peek.classList.remove("busy");
  };
  save.onclick = async () => {
    if (!(await openPasted())) return;
    const f = form();
    if (typeof f === "string") return say(f);
    save.classList.add("busy");
    try {
      const r = await api("davsync/save", f);
      if (!r.error) syncOpen = "";
      renderSync(r);
      if (r.error) return;
      refreshAfterSync();
    } catch (e) {
      save.classList.remove("busy");
      say(e.message);
    }
  };
  return ed;
};

// Only the Android host opts in. The ordinary desktop keeps its saved-path API.
// A failed JSON response must never become a file with a backup extension.
async function androidHostBackupDownload(body) {
  const response = await fetch("/api/backup/export", {
    method: "POST", credentials: "same-origin", mode: "same-origin", redirect: "error", cache: "no-store",
    headers: { "Content-Type": "application/json", Accept: "application/octet-stream" },
    body: JSON.stringify({ ...body, sink: "app" }),
  });
  const type = (response.headers.get("Content-Type") || "").split(";")[0].trim().toLowerCase();
  if (!response.ok || type !== "application/octet-stream" ||
      response.headers.get("Content-Disposition") !== 'attachment; filename="magpie.magpie-backup"') {
    throw new Error(t("Export") + ": " + t("Try again"));
  }
  const blob = await response.blob();
  if (!blob.size) throw new Error(t("Export") + ": " + t("Try again"));
  // Keep a retry button for browsers that require a fresh user gesture. A retry
  // downloads these same sealed bytes; it does not repeat the export POST.
  return () => {
    const a = document.createElement("a");
    const url = URL.createObjectURL(blob);
    try {
      a.href = url;
      a.download = "magpie.magpie-backup";
      document.body.append(a);
      a.click();
    }
    finally {
      a.remove();
      // Revoking immediately can cancel the browser's asynchronous download.
      setTimeout(() => URL.revokeObjectURL(url), 60e3);
    }
  };
}

// A settings tab or the whole view can stay connected while hidden. Never
// start an unsolicited download from a hidden page, tab, or background document.
function androidHostBackupFormActive(ed) {
  if (!ed.isConnected || document.visibilityState !== "visible") return false;
  for (let node = ed; node; node = node.parentElement) {
    if (node.hidden) return false;
  }
  return true;
}

